import zen from 'zen';

/** @type {Handler} **/
export const handler = async (input) => {

  // 1 Parámetros de regla
  const parameterBillingItemCodeForAmount = input?.parametros_de_la_regla?.parameter_billingItem_code_for_amount ?? null;
  const billingItemCode = input?.parametros_de_la_regla?.parameter_billingItem_code ?? null;

  if (!parameterBillingItemCodeForAmount || parameterBillingItemCodeForAmount.trim() === "") {
    return {
      ...input,
      result: {
        rule_description: "parameter_billingItem_code_for_amount is missing or invalid",
        status: "ERROR",
      }
    };
  }

  if (!billingItemCode || billingItemCode.trim() === "") {
    return {
      ...input,
      result: {
        rule_description: "parameter_billingItem_code is missing or invalid",
        status: "ERROR",
      }
    };
  }

  // 2 Buscar importe base desde billing_items (ejemplo: "consumo")
  const activeEnergyBillingItems = input?.tsl_wo_work_order_attribute?.billing_items?.active_energy_billing_items ?? [];
  const billingItemForAmount = activeEnergyBillingItems.find(item => item.legacy_billing_item_id === parameterBillingItemCodeForAmount);

  if (!billingItemForAmount) {
    return {
      ...input,
      result: {
        rule_description: `The parameter_billingItem_code_for_amount '${parameterBillingItemCodeForAmount}' could not be found in active_energy_billing_items`,
        status: "ERROR",
      }
    };
  }

  const rawAmount = billingItemForAmount.billing_item_amount;
  const active_energy_amount = Number(rawAmount);
  if (isNaN(active_energy_amount)) {
    return {
      ...input,
      result: {
        rule_description: `Invalid active_energy_amount value: ${rawAmount}`,
        status: "ERROR",
      }
    };
  }

  // 3 Leer porcentaje desde custom_custom_graduated_pricing_and_unique_percentage_and_unique_percentage
  const rawPercentage = input?.custom_graduated_pricing_and_unique_percentage?.percentage;
  if (rawPercentage === undefined || rawPercentage === null || String(rawPercentage).trim() === "") {
    return {
      ...input,
      result: {
        rule_description: "percentage is missing or empty",
        status: "ERROR",
      }
    };
  }

  const porcentajeGlobal = Number(rawPercentage);
  if (isNaN(porcentajeGlobal)) {
    return {
      ...input,
      result: {
        rule_description: `Invalid percentage value: ${rawPercentage}`,
        status: "ERROR",
      }
    };
  }

  // 4 Filtrar los rangos con el billingItemCode y ordenarlos por límite superior
  const prices = Array.isArray(input?.custom_graduated_pricing_and_unique_percentage?.prices)
    ? input.custom_graduated_pricing_and_unique_percentage.prices
    : [];

  const filteredRanges = prices
    .filter(r => r.code === billingItemCode) // ← aquí se usa "code"
    .sort((a, b) => Number(a.interval_high ?? 0) - Number(b.interval_high ?? 0))
    .map(r => ({
      limite: Number(r.interval_high),
      precio: Number(r.base_price),
      porcentaje: porcentajeGlobal // ⚡ viene desde custom_custom_graduated_pricing_and_unique_percentage_and_unique_percentage
    }));

  if (filteredRanges.length === 0) {
    return {
      ...input,
      result: {
        rule_description: `No prices found for billingItemCode '${billingItemCode}' in custom_graduated_pricing_and_unique_percentage.prices`,
        status: "ERROR"
      }
    };
  }

  // 5 Seleccionar el rango aplicable al importe
  let limite_anterior = 0;
  let i = 0;
  for (; i < filteredRanges.length; i++) {
    const rango = filteredRanges[i];
    if (
      (active_energy_amount >= limite_anterior && active_energy_amount <= rango.limite && rango.limite !== 999999999) ||
      (active_energy_amount >= limite_anterior && rango.limite === 999999999)
    ) {
      break;
    }
    limite_anterior = rango.limite;
  }
  if (i >= filteredRanges.length) i = filteredRanges.length - 1;
  const rangoSeleccionado = filteredRanges[i];

  // 6 Calcular importe de alumbrado (mayor entre precio fijo y % del importe)
  let importe_alumbrado = 0;
  const valorPorcentaje = active_energy_amount * (rangoSeleccionado.porcentaje / 100);
  importe_alumbrado = Math.max(rangoSeleccionado.precio, valorPorcentaje);
  
  const billingItems = input.tsl_wo_work_order_attribute.billing_items.public_lighting_billing_items;
  const billingItem = billingItems.find(item => item.legacy_billing_item_id === billingItemCode);

  if (!billingItem) {
    return {
      ...input,
        result: {
          rule_description: 'The parameter_billingItem_code ' + billingItemCode + ' could not be found in the billing concepts structure',
          status: 'ERROR',
        }
    };
  }
  billingItem.billing_item_amount = importe_alumbrado;

  // 7 Retornar resultado
  return {
    ...input,
    result: {
      total_amount: importe_alumbrado,
      status: "OK",
      rule_description: "Public lighting amount calculation rule completed"
    }
  };

};
